struct mm_struct *init_mm(struct mm_struct *mm, struct task_struct *p, struct user_namespace *user_ns) {
    if (!mm)
        return NULL;

    /* Initialize memory mappings */
    mm->mmap = NULL;
    mm->mmap_cache = NULL;
    mm->get_unmapped_area = NULL;

    /* Set reference count to 1 (initial reference) */
    atomic_set(&mm->mm_users, 1);
    atomic_set(&mm->mm_count, 1);

    /* Initialize locks */
    spin_lock_init(&mm->page_table_lock);
    mutex_init(&mm->mmap_lock);

    /* Setup flags based on current process's memory management state */
    if (current->mm) {
        mm->flags = current->mm->flags;
    } else {
        mm->flags = 0;
    }

    /* Allocate page tables */
    mm->pgd = get_pgd();
    if (!mm->pgd) {
        return NULL;
    }

    /* Initialize new context for the task */
    if (init_new_context(p, mm)) {
        free_pgd(mm->pgd);
        return NULL;
    }

    mm->task_size = TASK_SIZE;
    mm->user_ns = get_user_ns(user_ns);

    return mm;
}
